import { IntlMessageFormat } from "intl-messageformat";

import { hansToHk, hansToTw } from "../../src/lib/opencc";

export type MessageTree = { [key: string]: string | MessageTree };

export const GENERATED_KEY = "_generated";
export const GENERATED_NOTICE =
  "DO NOT EDIT - generated by `pnpm i18n:build` from zh-Hans.json + overrides";

export const SOURCE_LOCALES = ["de", "zh-Hans"] as const;
export const GENERATED_LOCALES = ["zh-Hant-HK", "zh-Hant-TW"] as const;

const CONVERTERS: Record<(typeof GENERATED_LOCALES)[number], (s: string) => string> = {
  "zh-Hant-HK": hansToHk,
  "zh-Hant-TW": hansToTw,
};

function isTree(value: unknown): value is MessageTree {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Flattens a nested message tree to dot-separated keys. `_generated` is ignored. */
export function flatten(tree: MessageTree, prefix = ""): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(tree)) {
    if (prefix === "" && key === GENERATED_KEY) continue;
    const path = prefix ? `${prefix}.${key}` : key;
    if (isTree(value)) Object.assign(out, flatten(value, path));
    else out[path] = value;
  }
  return out;
}

function convertTree(tree: MessageTree, convert: (s: string) => string): MessageTree {
  const out: MessageTree = {};
  for (const [key, value] of Object.entries(tree)) {
    out[key] = isTree(value) ? convertTree(value, convert) : convert(value);
  }
  return out;
}

/** Deep merge; values from `override` win. */
export function deepMerge(base: MessageTree, override: MessageTree): MessageTree {
  const out: MessageTree = { ...base };
  for (const [key, value] of Object.entries(override)) {
    const existing = out[key];
    out[key] = isTree(value) && isTree(existing) ? deepMerge(existing, value) : value;
  }
  return out;
}

/** Generates a Traditional-Chinese message file: OpenCC(zh-Hans) deep-merged with overrides. */
export function buildHant(
  locale: (typeof GENERATED_LOCALES)[number],
  hans: MessageTree,
  overrides: MessageTree,
): MessageTree {
  const converted = convertTree(hans, CONVERTERS[locale]);
  return { [GENERATED_KEY]: GENERATED_NOTICE, ...deepMerge(converted, overrides) };
}

export type CheckInput = {
  de: MessageTree;
  "zh-Hans": MessageTree;
  "zh-Hant-HK": MessageTree;
  "zh-Hant-TW": MessageTree;
  overrides: { "zh-Hant-HK": MessageTree; "zh-Hant-TW": MessageTree };
};

/** Returns a list of human-readable problems; empty means everything is consistent. */
export function checkMessages(input: CheckInput): string[] {
  const errors: string[] = [];
  const flat = {
    de: flatten(input.de),
    "zh-Hans": flatten(input["zh-Hans"]),
    "zh-Hant-HK": flatten(input["zh-Hant-HK"]),
    "zh-Hant-TW": flatten(input["zh-Hant-TW"]),
  };
  const allKeys = new Set(Object.values(flat).flatMap((m) => Object.keys(m)));

  for (const [locale, messages] of Object.entries(flat)) {
    for (const key of [...allKeys].sort()) {
      const value = messages[key];
      if (value === undefined) errors.push(`${locale}: missing key "${key}"`);
      else if (value.trim() === "") errors.push(`${locale}: empty value for "${key}"`);
      else {
        try {
          new IntlMessageFormat(value, locale);
        } catch (error) {
          errors.push(`${locale}: invalid ICU message "${key}": ${(error as Error).message}`);
        }
      }
    }
  }

  for (const locale of GENERATED_LOCALES) {
    const hansKeys = new Set(Object.keys(flat["zh-Hans"]));
    for (const key of Object.keys(flatten(input.overrides[locale]))) {
      if (!hansKeys.has(key)) errors.push(`overrides/${locale}: unknown key "${key}"`);
    }
    const expected = buildHant(locale, input["zh-Hans"], input.overrides[locale]);
    if (JSON.stringify(expected) !== JSON.stringify(input[locale])) {
      errors.push(`${locale}: generated file is stale or edited by hand, run \`pnpm i18n:build\``);
    }
  }
  return errors;
}
